3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request that is missing or blank in any required owner field, before
13	 * {@link BuildOwner} maps the body to an entity. Runs first so the body is read once here
14	 * and republished for later steps.
15	 */
16	public class ValidateNewOwner {
17	
18	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
19	            throws MissingOwnerFieldsException {
20	        List<String> missing = new ArrayList<>();
21	        checkPresent("firstName", request.getFirstName(), missing);
22	        checkPresent("lastName", request.getLastName(), missing);
23	        checkPresent("address", request.getAddress(), missing);
24	        checkPresent("city", request.getCity(), missing);
25	        checkPresent("telephone", request.getTelephone(), missing);
26	        if (!missing.isEmpty()) {
27	            throw new MissingOwnerFieldsException(missing);
28	        }
29	        validated.set(request);
30	    }
31	
32	    private static void checkPresent(String name, String value, List<String> missing) {
33	        if (value == null || value.isBlank()) {
34	            missing.add(name);
35	        }
36	    }
37	}
