1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create request whose E.164 telephone is already used by another owner, so the
11	 * pair maps to a 409. Runs after {@link NormalizeOwnerTelephone} has canonicalized the
12	 * request's telephone to E.164, and before {@link BuildOwner} maps it to an entity. Existing
13	 * owners are compared on their E.164 telephone too, so formatting differences do not hide a
14	 * collision.
15	 */
16	public class EnsureUniqueTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateTelephoneException {
20	        String telephone = request.getTelephone();
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone()))) {
23	                throw new DuplicateTelephoneException(telephone);
24	            }
25	        }
26	    }
27	}
