2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's customer code before it is saved. The code is formatted
9	 * {@code <LAST3>-<NNNN>}, where {@code LAST3} is the upper-cased first three letters of
10	 * the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to one
11	 * more than the current number of owners (e.g. {@code SMI-0007}). Runs after
12	 * {@link BuildOwner} has produced the entity and before {@link SaveOwner} persists it,
13	 * mutating the built owner in place.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        int sequence = ownerRepository.findAll().size() + 1;
19	        owner.setCustomerCode(format(owner.getLastName(), sequence));
20	    }
21	
22	    private static String format(String lastName, int sequence) {
23	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
24	        return String.format("%s-%04d", prefix, sequence);
25	    }
26	}
